import java.util.*;

public class Main {
    // Thread-safe by confinement of state behind one lock
    static class Counter {
        private final Object lock = new Object(); // private lock, not "this"
        private int value = 0;
        void increment() { synchronized (lock) { value++; } } // read-modify-write is atomic
        int get() { synchronized (lock) { return value; } }
    }

    public static void main(String[] args) throws Exception {
        Counter c = new Counter();
        List<Thread> ts = new ArrayList<>();
        for (int t = 0; t < 4; t++) {
            Thread th = new Thread(() -> { for (int i = 0; i < 1000; i++) c.increment(); });
            ts.add(th);
            th.start();
        }
        for (Thread th : ts) th.join(); // wait for all workers
        System.out.println("threads=4 increments each=1000");
        System.out.println("expected=4000 got=" + c.get());
    }
}

