import threading

class Counter:
    def __init__(self):
        self._lock = threading.Lock()  # private lock guarding _value
        self._value = 0

    def increment(self):
        with self._lock:               # read-modify-write is atomic
            self._value += 1

    def get(self):
        with self._lock:
            return self._value

c = Counter()

def work():
    for _ in range(1000):
        c.increment()

threads = [threading.Thread(target=work) for _ in range(4)]
for t in threads:
    t.start()
for t in threads:
    t.join()  # wait for all workers
print("threads=4 increments each=1000")
print("expected=4000 got=%d" % c.get())

