import java.util.concurrent.locks.*;

public class Main {
    static class Account {
        final int id; int balance; final Lock lock = new ReentrantLock();
        Account(int id, int b) { this.id = id; this.balance = b; }
    }

    // Deadlock avoided: always lock the account with the smaller id first
    static void transfer(Account from, Account to, int amt) {
        Account first = from.id < to.id ? from : to;
        Account second = first == from ? to : from;
        first.lock.lock();
        try {
            second.lock.lock();
            try { from.balance -= amt; to.balance += amt; }
            finally { second.lock.unlock(); }
        } finally { first.lock.unlock(); }
    }

    public static void main(String[] args) throws Exception {
        Account a = new Account(1, 1000), b = new Account(2, 1000);
        Thread t1 = new Thread(() -> { for (int i = 0; i < 100; i++) transfer(a, b, 10); });
        Thread t2 = new Thread(() -> { for (int i = 0; i < 100; i++) transfer(b, a, 5); });
        System.out.println("start A=1000 B=1000");
        t1.start(); t2.start(); t1.join(); t2.join(); // opposite directions, no deadlock
        System.out.println("end A=" + a.balance + " B=" + b.balance + " total=" + (a.balance + b.balance));
    }
}

