import java.util.*;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.*;
import java.util.concurrent.locks.*;

public class Main {
    static int lockCount = 0;                                // guarded by rl
    static final ReentrantLock rl = new ReentrantLock();
    static final AtomicInteger atomic = new AtomicInteger(); // lock-free CAS on one variable

    public static void main(String[] args) throws Exception {
        List<Thread> ts = new ArrayList<>();
        for (int t = 0; t < 4; t++) {
            Thread th = new Thread(() -> {
                for (int i = 0; i < 1000; i++) {
                    rl.lock();
                    try { lockCount++; } finally { rl.unlock(); } // always unlock in finally
                    atomic.incrementAndGet();
                }
            });
            ts.add(th); th.start();
        }
        for (Thread th : ts) th.join();
        System.out.println("lock-guarded=" + lockCount + " atomic=" + atomic.get());
        rl.lock(); // hold the lock, then let another thread try with a timeout
        Thread other = new Thread(() -> {
            try { System.out.println("other thread tryLock while held: " + rl.tryLock(50, TimeUnit.MILLISECONDS)); }
            catch (InterruptedException e) { }
        });
        other.start(); other.join();
        rl.unlock();
    }
}

