const { Worker, isMainThread, workerData } = require('worker_threads');
// shared memory: [0] = lock flag, [1] = counter guarded by the lock, [2] = atomic counter
function tryLock(m, ms) {
  const end = Date.now() + ms;
  while (Atomics.compareExchange(m, 0, 0, 1) !== 0) {
    const left = end - Date.now();
    if (left <= 0) return false;                 // give up instead of waiting forever
    Atomics.wait(m, 0, 1, left);
  }
  return true;
}
function unlock(m) { Atomics.store(m, 0, 0); Atomics.notify(m, 0, 1); }

if (isMainThread) {
  const m = new Int32Array(new SharedArrayBuffer(12));
  let done = 0;
  const spawn = (mode, cb) => new Worker(__filename, { workerData: { buf: m.buffer, mode } }).on('exit', cb);
  for (let t = 0; t < 4; t++) spawn('count', () => {
    if (++done < 4) return;
    console.log("lock-guarded=" + m[1] + " atomic=" + Atomics.load(m, 2));
    tryLock(m, 1000); // hold the lock, then let another thread try with a timeout
    spawn('try', () => unlock(m));
  });
} else {
  const m = new Int32Array(workerData.buf);
  if (workerData.mode === 'count') {
    for (let i = 0; i < 1000; i++) {
      tryLock(m, 5000); m[1]++; unlock(m); // plain increment is safe only inside the lock
      Atomics.add(m, 2, 1);                // lock-free atomic add
    }
  } else {
    console.log("other thread tryLock while held: " + tryLock(m, 50));
  }
}

