import java.util.*;
import java.util.concurrent.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Map<String, Integer> syncMap = Collections.synchronizedMap(new HashMap<>());
        Map<String, Integer> chm = new ConcurrentHashMap<>();
        List<Thread> ts = new ArrayList<>();
        for (int t = 0; t < 4; t++) {
            Thread th = new Thread(() -> {
                for (int i = 0; i < 1000; i++) {
                    // synchronizedMap: each call is atomic, but get-then-put is NOT
                    Integer old = syncMap.get("k");
                    syncMap.put("k", old == null ? 1 : old + 1);
                    // ConcurrentHashMap: one atomic compound method
                    chm.merge("k", 1, Integer::sum);
                }
            });
            ts.add(th); th.start();
        }
        for (Thread th : ts) th.join();
        System.out.println("expected = 4000");
        System.out.println("atomic merge = " + chm.get("k"));
        System.out.println("get-then-put never above 4000 = " + (syncMap.get("k") <= 4000) + " (may lose updates)");
    }
}

