// JS has one thread, but async code can still interleave at every await.
const slow = new Map();  // get, await, put: another task can run in between
const atomic = new Map(); // read and write in one synchronous step

// like merge(k, 1, sum): no await inside, so nothing can interleave
function merge(k) { atomic.set(k, (atomic.get(k) || 0) + 1); }

async function work() {
  for (let i = 0; i < 1000; i++) {
    const old = slow.get("k");
    await null;                            // a yield point, like a thread switch
    slow.set("k", old === undefined ? 1 : old + 1);
    merge("k");
  }
}

async function main() {
  await Promise.all([work(), work(), work(), work()]);
  console.log("expected = 4000");
  console.log("atomic merge = " + atomic.get("k"));
  console.log("get-then-put never above 4000 = " + (slow.get("k") <= 4000) + " (may lose updates)");
}
main();

