public class Main {
    // Token bucket in milli-tokens: 1 request costs 1000, refill 1 milli-token per ms
    static class Bucket {
        final long capacity, cost = 1000; long tokens, last;
        Bucket(long capTokens, long now) { capacity = capTokens * 1000; tokens = capacity; last = now; }
        synchronized long tryAcquire(long now) {            // refill + check + take in one critical section
            tokens = Math.min(capacity, tokens + (now - last)); // lazy refill, no timer thread
            last = now;
            if (tokens >= cost) { tokens -= cost; return 0; }
            return cost - tokens;                            // ms until next token = Retry-After
        }
    }

    public static void main(String[] args) {
        Bucket b = new Bucket(3, 0);                         // burst 3, 1 token per second
        long[] times = {0, 0, 0, 0, 500, 1000, 1500, 2500, 3000}; // injected fake clock (ms)
        for (long t : times) {
            long wait = b.tryAcquire(t);
            System.out.println("t=" + t + "ms " + (wait == 0 ? "allow" : "deny retryAfter=" + wait + "ms"));
        }
    }
}

