import java.util.*;

public class Main {
    static final int W = 1000, N = 5;

    public static void main(String[] args) {
        int[] times = {900, 900, 900, 900, 900, 1100, 1100, 1100, 1100, 1100};
        int[] fixed = new int[2], log = new int[2], ctr = new int[2];
        Map<Integer, Integer> counts = new HashMap<>();   // fixed window: one counter per window
        Deque<Integer> stamps = new ArrayDeque<>();        // sliding log: accepted timestamps
        int prev = 0, cur = 0, curWin = 0;                 // sliding counter: two numbers
        for (int i = 0; i < times.length; i++) {
            int t = times[i], burst = i < 5 ? 0 : 1, win = t / W;
            int c = counts.getOrDefault(win, 0);
            if (c < N) { counts.put(win, c + 1); fixed[burst]++; }
            while (!stamps.isEmpty() && stamps.peekFirst() <= t - W) stamps.pollFirst(); // evict old
            if (stamps.size() < N) { stamps.addLast(t); log[burst]++; }                   // only accepted are stored
            if (win != curWin) { prev = (win == curWin + 1) ? cur : 0; cur = 0; curWin = win; }
            int est = prev * (W - t % W) / W + cur;                                        // weighted estimate
            if (est < N) { cur++; ctr[burst]++; }
        }
        System.out.println("burst of 5 at t=900, burst of 5 at t=1100 (limit 5 per 1000ms)");
        System.out.println("fixed window   allowed: " + fixed[0] + " then " + fixed[1]);
        System.out.println("sliding log    allowed: " + log[0] + " then " + log[1]);
        System.out.println("sliding counter allowed: " + ctr[0] + " then " + ctr[1]);
    }
}

