const times = [900, 900, 900, 900, 900, 1100, 1100, 1100, 1100, 1100];
const fixed = [0, 0], log = [0, 0], ctr = [0, 0];
const counts = new Map();   // fixed window: one counter per window
let stamps = [];            // sliding log: accepted timestamps
let prev = 0, cur = 0, curWin = 0; // sliding counter: two numbers
times.forEach((t, i) => {
  const burst = i < 5 ? 0 : 1, win = Math.floor(t / W);
  const c = counts.get(win) || 0;
  if (c < N) { counts.set(win, c + 1); fixed[burst]++; }
  while (stamps.length && stamps[0] <= t - W) stamps.shift(); // evict old
  if (stamps.length < N) { stamps.push(t); log[burst]++; }     // only accepted are stored
  if (win !== curWin) { prev = (win === curWin + 1) ? cur : 0; cur = 0; curWin = win; }
  const est = Math.floor(prev * (W - t % W) / W) + cur;        // weighted estimate
  if (est < N) { cur++; ctr[burst]++; }
});
console.log("burst of 5 at t=900, burst of 5 at t=1100 (limit 5 per 1000ms)");
console.log("fixed window   allowed: " + fixed[0] + " then " + fixed[1]);
console.log("sliding log    allowed: " + log[0] + " then " + log[1]);
console.log("sliding counter allowed: " + ctr[0] + " then " + ctr[1]);

