#include <bits/stdc++.h>
using namespace std;

int main() {
    const int W = 1000, N = 5;
    vector<int> times = {900, 900, 900, 900, 900, 1100, 1100, 1100, 1100, 1100};
    int fixed[2] = {0, 0}, lg[2] = {0, 0}, ctr[2] = {0, 0};
    map<int, int> counts;   // fixed window: one counter per window
    deque<int> stamps;      // sliding log: accepted timestamps
    int prev = 0, cur = 0, curWin = 0;  // sliding counter: two numbers
    for (int i = 0; i < (int)times.size(); i++) {
        int t = times[i], burst = i < 5 ? 0 : 1, win = t / W;
        if (counts[win] < N) { counts[win]++; fixed[burst]++; }
        while (!stamps.empty() && stamps.front() <= t - W) stamps.pop_front();  // evict old
        if ((int)stamps.size() < N) { stamps.push_back(t); lg[burst]++; }       // only accepted are stored
        if (win != curWin) { prev = (win == curWin + 1) ? cur : 0; cur = 0; curWin = win; }
        int est = prev * (W - t % W) / W + cur;                                  // weighted estimate
        if (est < N) { cur++; ctr[burst]++; }
    }
    cout << "burst of 5 at t=900, burst of 5 at t=1100 (limit 5 per 1000ms)" << endl;
    cout << "fixed window   allowed: " << fixed[0] << " then " << fixed[1] << endl;
    cout << "sliding log    allowed: " << lg[0] << " then " << lg[1] << endl;
    cout << "sliding counter allowed: " << ctr[0] << " then " << ctr[1] << endl;
}

