class Program
{
    const int W = 1000, N = 5;

    static void Main()
    {
        int[] times = { 900, 900, 900, 900, 900, 1100, 1100, 1100, 1100, 1100 };
        int[] fixedW = new int[2], log = new int[2], ctr = new int[2];
        Dictionary<int, int> counts = new Dictionary<int, int>(); // fixed window: one counter per window
        LinkedList<int> stamps = new LinkedList<int>();            // sliding log: accepted timestamps
        int prev = 0, cur = 0, curWin = 0;                         // sliding counter: two numbers
        for (int i = 0; i < times.Length; i++)
        {
            int t = times[i], burst = i < 5 ? 0 : 1, win = t / W;
            int c = 0; counts.TryGetValue(win, out c);
            if (c < N) { counts[win] = c + 1; fixedW[burst]++; }
            while (stamps.Count > 0 && stamps.First.Value <= t - W) stamps.RemoveFirst(); // evict old
            if (stamps.Count < N) { stamps.AddLast(t); log[burst]++; }                     // only accepted are stored
            if (win != curWin) { prev = (win == curWin + 1) ? cur : 0; cur = 0; curWin = win; }
            int est = prev * (W - t % W) / W + cur;                                        // weighted estimate
            if (est < N) { cur++; ctr[burst]++; }
        }
        Console.WriteLine("burst of 5 at t=900, burst of 5 at t=1100 (limit 5 per 1000ms)");
        Console.WriteLine("fixed window   allowed: " + fixedW[0] + " then " + fixedW[1]);
        Console.WriteLine("sliding log    allowed: " + log[0] + " then " + log[1]);
        Console.WriteLine("sliding counter allowed: " + ctr[0] + " then " + ctr[1]);
    }
}

