import java.util.*;
import java.util.concurrent.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BlockingQueue<Integer> q = new ArrayBlockingQueue<>(2); // bounded: put() blocks when full
        final int POISON = -1;                                   // tells the consumer to stop
        List<Integer> seen = new ArrayList<>();
        Thread consumer = new Thread(() -> {
            try {
                while (true) {
                    int v = q.take();                            // blocks when empty
                    if (v == POISON) break;
                    seen.add(v);
                }
            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        });
        Thread producer = new Thread(() -> {
            try {
                for (int i = 1; i <= 5; i++) q.put(i);           // backpressure when consumer is slow
                q.put(POISON);                                   // one pill per consumer
            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        });
        consumer.start(); producer.start();
        producer.join(); consumer.join();
        int sum = 0; for (int v : seen) sum += v;
        System.out.println("produced 1..5, capacity 2");
        System.out.println("consumed in order " + seen + " sum=" + sum);
    }
}

