// Async bounded queue: put waits when full, take waits when empty (backpressure)
class BoundedQueue {
  constructor(cap) { this.cap = cap; this.items = []; this.takers = []; this.putters = []; }
  async put(v) {
    while (this.items.length >= this.cap) await new Promise(r => this.putters.push(r)); // while, not if
    this.items.push(v);
    if (this.takers.length) this.takers.shift()(); // wake one waiting consumer
  }
  async take() {
    while (this.items.length === 0) await new Promise(r => this.takers.push(r));
    const v = this.items.shift();
    if (this.putters.length) this.putters.shift()(); // wake one waiting producer
    return v;
  }
}

async function main() {
  const q = new BoundedQueue(2), POISON = -1, seen = [];
  const consumer = (async () => {
    for (;;) { const v = await q.take(); if (v === POISON) break; seen.push(v); }
  })();
  const producer = (async () => {
    for (let i = 1; i <= 5; i++) await q.put(i);
    await q.put(POISON); // one pill per consumer
  })();
  await Promise.all([producer, consumer]);
  console.log("produced 1..5, capacity 2");
  console.log("consumed in order [" + seen.join(", ") + "] sum=" + seen.reduce((a, b) => a + b, 0));
}
main();

