#include <bits/stdc++.h>
using namespace std;

// Bounded buffer: one mutex, two condition variables, wait in a while loop
class BoundedQueue {
    queue<int> q; size_t cap; mutex m; condition_variable notFull, notEmpty;
public:
    BoundedQueue(size_t c) : cap(c) {}
    void put(int v) {
        unique_lock<mutex> lk(m);
        while (q.size() == cap) notFull.wait(lk);   // while, not if: guards spurious wakeups
        q.push(v);
        notEmpty.notify_one();                      // signal the opposite condition
    }
    int take() {
        unique_lock<mutex> lk(m);
        while (q.empty()) notEmpty.wait(lk);
        int v = q.front(); q.pop();
        notFull.notify_one();
        return v;
    }
};

int main() {
    BoundedQueue q(2);
    const int POISON = -1;
    vector<int> seen;
    thread consumer([&] { for (;;) { int v = q.take(); if (v == POISON) break; seen.push_back(v); } });
    thread producer([&] { for (int i = 1; i <= 5; i++) q.put(i); q.put(POISON); });
    producer.join(); consumer.join();
    int sum = 0; string s;
    for (size_t i = 0; i < seen.size(); i++) { sum += seen[i]; s += (i ? ", " : "") + to_string(seen[i]); }
    cout << "produced 1..5, capacity 2" << endl;
    cout << "consumed in order [" << s << "] sum=" << sum << endl;
}

