import java.util.*;

public class Main {
    // LinkedHashMap in access order: get() relinks the entry, so get needs the lock too
    static class LruCache<K, V> {
        private final LinkedHashMap<K, V> map;
        LruCache(int cap) {
            map = new LinkedHashMap<K, V>(16, 0.75f, true) {
                protected boolean removeEldestEntry(Map.Entry<K, V> e) { return size() > cap; }
            };
        }
        synchronized V get(K k) { return map.get(k); }        // a read is a write here
        synchronized void put(K k, V v) { map.put(k, v); }
        synchronized String keys() { return map.keySet().toString(); }
    }

    public static void main(String[] args) {
        LruCache<String, Integer> c = new LruCache<>(2);
        c.put("a", 1); c.put("b", 2);
        System.out.println("get a -> " + c.get("a"));          // a becomes most recent
        c.put("c", 3);                                          // evicts b
        System.out.println("get b -> " + c.get("b"));
        c.put("d", 4);                                          // evicts a
        System.out.println("get a -> " + c.get("a"));
        System.out.println("get c -> " + c.get("c"));
        System.out.println("keys oldest to newest: " + c.keys());
    }
}

