// Map keeps insertion order, so re-inserting a key moves it to the newest end
class LruCache {
  constructor(cap) { this.cap = cap; this.map = new Map(); }
  get(k) {
    if (!this.map.has(k)) return null;
    const v = this.map.get(k);
    this.map.delete(k); this.map.set(k, v); // move to most recent
    return v;
  }
  put(k, v) {
    this.map.delete(k); this.map.set(k, v);
    if (this.map.size > this.cap) this.map.delete(this.map.keys().next().value); // evict oldest
  }
  keys() { return "[" + [...this.map.keys()].join(", ") + "]"; }
}
