#include <bits/stdc++.h>
using namespace std;

class LruCache {
    size_t cap;
    list<pair<string, int>> items;  // front = oldest, back = newest
    unordered_map<string, list<pair<string, int>>::iterator> idx;
    mutex m;                        // get() relinks, so get needs the lock too
public:
    LruCache(size_t c) : cap(c) {}
    string get(const string& k) {
        lock_guard<mutex> g(m);
        auto it = idx.find(k);
        if (it == idx.end()) return "null";
        items.splice(items.end(), items, it->second);  // move to most recent
        return to_string(it->second->second);
    }
    void put(const string& k, int v) {
        lock_guard<mutex> g(m);
        auto it = idx.find(k);
        if (it != idx.end()) { items.erase(it->second); idx.erase(it); }
        items.push_back({k, v});
        idx[k] = prev(items.end());
        if (items.size() > cap) { idx.erase(items.front().first); items.pop_front(); }  // evict oldest
    }
    string keys() {
        lock_guard<mutex> g(m);
        string s = "[";
        for (auto& p : items) s += (s.size() > 1 ? ", " : "") + p.first;
        return s + "]";
    }
};

int main() {
    LruCache c(2);
    c.put("a", 1); c.put("b", 2);
    cout << "get a -> " << c.get("a") << endl;  // a becomes most recent
    c.put("c", 3);                               // evicts b
    cout << "get b -> " << c.get("b") << endl;
    c.put("d", 4);                               // evicts a
    cout << "get a -> " << c.get("a") << endl;
    cout << "get c -> " << c.get("c") << endl;
    cout << "keys oldest to newest: " << c.keys() << endl;
}

