using System;
using System.Collections.Generic;

class LruCache
{
    private readonly int cap;
    private readonly LinkedList<KeyValuePair<string, int>> items = new LinkedList<KeyValuePair<string, int>>(); // first = oldest
    private readonly Dictionary<string, LinkedListNode<KeyValuePair<string, int>>> idx = new Dictionary<string, LinkedListNode<KeyValuePair<string, int>>>();
    private readonly object lk = new object(); // get() relinks, so get needs the lock too
    public LruCache(int c) { cap = c; }

    public string Get(string k)
    {
        lock (lk)
        {
            LinkedListNode<KeyValuePair<string, int>> n;
            if (!idx.TryGetValue(k, out n)) return "null";
            items.Remove(n); items.AddLast(n); // move to most recent
            return n.Value.Value.ToString();
        }
    }

    public void Put(string k, int v)
    {
        lock (lk)
        {
            LinkedListNode<KeyValuePair<string, int>> n;
            if (idx.TryGetValue(k, out n)) items.Remove(n);
            idx[k] = items.AddLast(new KeyValuePair<string, int>(k, v));
            if (items.Count > cap) { idx.Remove(items.First.Value.Key); items.RemoveFirst(); } // evict oldest
        }
    }

    public string Keys()
    {
        lock (lk)
        {
            List<string> ks = new List<string>();
            foreach (KeyValuePair<string, int> p in items) ks.Add(p.Key);
            return "[" + string.Join(", ", ks) + "]";
        }
    }
}

class Program
{
    static void Main()
    {
        LruCache c = new LruCache(2);
        c.Put("a", 1); c.Put("b", 2);
        Console.WriteLine("get a -> " + c.Get("a")); // a becomes most recent
        c.Put("c", 3);                                // evicts b
        Console.WriteLine("get b -> " + c.Get("b"));
        c.Put("d", 4);                                // evicts a
        Console.WriteLine("get a -> " + c.Get("a"));
        Console.WriteLine("get c -> " + c.Get("c"));
        Console.WriteLine("keys oldest to newest: " + c.Keys());
    }
}

