import java.util.*;

public class Main {
    // O(1) LFU: key->value, key->freq, freq->keys in insertion order, plus minFreq
    static class Lfu {
        final int cap; int minFreq = 0;
        final Map<Integer, Integer> val = new HashMap<>(), freq = new HashMap<>();
        final Map<Integer, LinkedHashSet<Integer>> buckets = new HashMap<>();
        Lfu(int cap) { this.cap = cap; }

        private void touch(int k) {
            int f = freq.get(k);
            buckets.get(f).remove(k);
            if (buckets.get(f).isEmpty() && f == minFreq) minFreq++;  // old minimum bucket emptied
            freq.put(k, f + 1);
            buckets.computeIfAbsent(f + 1, x -> new LinkedHashSet<>()).add(k);
        }
        synchronized int get(int k) {                  // one lock: several structures change together
            if (!val.containsKey(k)) return -1;
            touch(k); return val.get(k);
        }
        synchronized void put(int k, int v) {
            if (cap == 0) return;
            if (val.containsKey(k)) { val.put(k, v); touch(k); return; }
            if (val.size() == cap) {                    // evict oldest key in the lowest-frequency bucket
                int victim = buckets.get(minFreq).iterator().next();
                buckets.get(minFreq).remove(victim); val.remove(victim); freq.remove(victim);
            }
            val.put(k, v); freq.put(k, 1);
            buckets.computeIfAbsent(1, x -> new LinkedHashSet<>()).add(k);
            minFreq = 1;
        }
    }

    public static void main(String[] args) {
        Lfu c = new Lfu(2);
        c.put(1, 1); c.put(2, 2);
        List<Integer> out = new ArrayList<>();
        out.add(c.get(1));      // freq of 1 is now 2
        c.put(3, 3);            // evicts 2 (lowest freq)
        out.add(c.get(2)); out.add(c.get(3));
        c.put(4, 4);            // 1 and 3 tie at freq 2, evicts older (1)
        out.add(c.get(1)); out.add(c.get(3)); out.add(c.get(4));
        System.out.println("capacity 2 results: " + out);
    }
}

