// O(1) LFU: key->value, key->freq, freq->Set of keys (Set keeps insertion order), plus minFreq
class Lfu {
  constructor(cap) { this.cap = cap; this.minFreq = 0; this.val = new Map(); this.freq = new Map(); this.buckets = new Map(); }
  touch(k) {
    const f = this.freq.get(k);
    this.buckets.get(f).delete(k);
    if (this.buckets.get(f).size === 0 && f === this.minFreq) this.minFreq++; // old minimum emptied
    this.freq.set(k, f + 1);
    if (!this.buckets.has(f + 1)) this.buckets.set(f + 1, new Set());
    this.buckets.get(f + 1).add(k);
  }
  get(k) {
    if (!this.val.has(k)) return -1;
    this.touch(k);
    return this.val.get(k);
  }
  put(k, v) {
    if (this.cap === 0) return;
    if (this.val.has(k)) { this.val.set(k, v); this.touch(k); return; }
    if (this.val.size === this.cap) { // evict oldest key in the lowest-frequency bucket
      const victim = this.buckets.get(this.minFreq).values().next().value;
      this.buckets.get(this.minFreq).delete(victim);
      this.val.delete(victim); this.freq.delete(victim);
    }
    this.val.set(k, v); this.freq.set(k, 1);
    if (!this.buckets.has(1)) this.buckets.set(1, new Set());
    this.buckets.get(1).add(k);
    this.minFreq = 1;
  }
}
