#include <bits/stdc++.h>
using namespace std;

// O(1) LFU: key->value/freq/position, freq->list of keys (front = oldest), plus minFreq
class Lfu {
    int cap, minFreq = 0;
    struct E { int val, freq; list<int>::iterator pos; };
    unordered_map<int, E> m;
    unordered_map<int, list<int>> buckets;
    mutex mu;  // several structures change together, so one lock
    void touch(int k) {
        E& e = m[k];
        buckets[e.freq].erase(e.pos);
        if (buckets[e.freq].empty() && e.freq == minFreq) minFreq++;  // old minimum emptied
        e.freq++;
        buckets[e.freq].push_back(k);
        e.pos = prev(buckets[e.freq].end());
    }
public:
    Lfu(int c) : cap(c) {}
    int get(int k) {
        lock_guard<mutex> g(mu);
        if (!m.count(k)) return -1;
        touch(k);
        return m[k].val;
    }
    void put(int k, int v) {
        lock_guard<mutex> g(mu);
        if (cap == 0) return;
        if (m.count(k)) { m[k].val = v; touch(k); return; }
        if ((int)m.size() == cap) {  // evict oldest key in the lowest-frequency bucket
            int victim = buckets[minFreq].front();
            buckets[minFreq].pop_front();
            m.erase(victim);
        }
        buckets[1].push_back(k);
        m[k] = {v, 1, prev(buckets[1].end())};
        minFreq = 1;
    }
};

int main() {
    Lfu c(2);
    c.put(1, 1); c.put(2, 2);
    vector<int> out;
    out.push_back(c.get(1));  // freq of 1 is now 2
    c.put(3, 3);              // evicts 2 (lowest freq)
    out.push_back(c.get(2)); out.push_back(c.get(3));
    c.put(4, 4);              // 1 and 3 tie at freq 2, evicts older (1)
    out.push_back(c.get(1)); out.push_back(c.get(3)); out.push_back(c.get(4));
    string s;
    for (size_t i = 0; i < out.size(); i++) s += (i ? ", " : "") + to_string(out[i]);
    cout << "capacity 2 results: [" << s << "]" << endl;
}

