using System;
using System.Collections.Generic;

class Lfu
{
    // O(1) LFU: key->value/freq/node, freq->linked list of keys (first = oldest), plus minFreq
    class Entry { public int Val, Freq; public LinkedListNode<int> Node; }
    private readonly int cap;
    private int minFreq = 0;
    private readonly Dictionary<int, Entry> map = new Dictionary<int, Entry>();
    private readonly Dictionary<int, LinkedList<int>> buckets = new Dictionary<int, LinkedList<int>>();
    private readonly object lk = new object(); // several structures change together, so one lock
    public Lfu(int c) { cap = c; }

    private void Add(int f, int k, Entry e)
    {
        if (!buckets.ContainsKey(f)) buckets[f] = new LinkedList<int>();
        e.Freq = f; e.Node = buckets[f].AddLast(k);
    }

    private void Touch(int k)
    {
        Entry e = map[k];
        buckets[e.Freq].Remove(e.Node);
        if (buckets[e.Freq].Count == 0 && e.Freq == minFreq) minFreq++; // old minimum emptied
        Add(e.Freq + 1, k, e);
    }

    public int Get(int k)
    {
        lock (lk) { if (!map.ContainsKey(k)) return -1; Touch(k); return map[k].Val; }
    }

    public void Put(int k, int v)
    {
        lock (lk)
        {
            if (cap == 0) return;
            if (map.ContainsKey(k)) { map[k].Val = v; Touch(k); return; }
            if (map.Count == cap) // evict oldest key in the lowest-frequency bucket
            {
                int victim = buckets[minFreq].First.Value;
                buckets[minFreq].RemoveFirst(); map.Remove(victim);
            }
            Entry e = new Entry(); e.Val = v; map[k] = e;
            Add(1, k, e);
            minFreq = 1;
        }
    }
}

class Program
{
    static void Main()
    {
        Lfu c = new Lfu(2);
        c.Put(1, 1); c.Put(2, 2);
        List<int> o = new List<int>();
        o.Add(c.Get(1));            // freq of 1 is now 2
        c.Put(3, 3);                // evicts 2 (lowest freq)
        o.Add(c.Get(2)); o.Add(c.Get(3));
        c.Put(4, 4);                // 1 and 3 tie at freq 2, evicts older (1)
        o.Add(c.Get(1)); o.Add(c.Get(3)); o.Add(c.Get(4));
        Console.WriteLine("capacity 2 results: [" + string.Join(", ", o) + "]");
    }
}

