import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;
import java.util.concurrent.atomic.*;

public class Main {
    static final String[] owner = new String[6];                 // null = AVAILABLE
    static final Lock[] locks = new Lock[6];

    // All-or-nothing: lock seats in sorted order (no deadlock), check all, then mark all
    static boolean book(String user, int... seats) {
        int[] s = seats.clone(); Arrays.sort(s);
        for (int id : s) locks[id].lock();
        try {
            for (int id : s) if (owner[id] != null) return false;
            for (int id : s) owner[id] = user;
            return true;
        } finally {
            for (int i = s.length - 1; i >= 0; i--) locks[s[i]].unlock();
        }
    }

    public static void main(String[] args) throws Exception {
        for (int i = 0; i < 6; i++) locks[i] = new ReentrantLock();
        AtomicInteger wins = new AtomicInteger();
        CountDownLatch start = new CountDownLatch(1);              // release all threads together
        List<Thread> ts = new ArrayList<>();
        for (int u = 0; u < 4; u++) {
            final String name = "user" + u;
            final int[] want = (u % 2 == 0) ? new int[]{1, 2} : new int[]{2, 1}; // opposite order
            Thread t = new Thread(() -> {
                try { start.await(); } catch (InterruptedException e) { return; }
                if (book(name, want)) wins.incrementAndGet();
            });
            ts.add(t); t.start();
        }
        start.countDown();
        for (Thread t : ts) t.join();
        System.out.println("4 users all want seats 1 and 2, successes = " + wins.get());
        System.out.println("seat 3 for someone else: " + book("late", 3));
        System.out.println("seat 1 and 2 have same owner: " + owner[1].equals(owner[2]));
    }
}

