import java.lang.management.*;
import java.util.concurrent.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Object a = new Object(), b = new Object();
        CyclicBarrier bothHoldFirst = new CyclicBarrier(2);   // make the bad interleaving certain
        Thread t1 = new Thread(() -> lockBoth(a, b, bothHoldFirst), "worker-1"); // takes A then B
        Thread t2 = new Thread(() -> lockBoth(b, a, bothHoldFirst), "worker-2"); // takes B then A: circular wait
        t1.setDaemon(true); t2.setDaemon(true);                // so the JVM can still exit
        t1.start(); t2.start();
        ThreadMXBean mx = ManagementFactory.getThreadMXBean();
        long[] ids = null;
        for (int i = 0; i < 50 && ids == null; i++) {          // poll up to ~2.5 s
            Thread.sleep(50);
            ids = mx.findDeadlockedThreads();                  // same data jstack prints as "Found one Java-level deadlock"
        }
        System.out.println("deadlock detected: " + (ids != null));
        System.out.println("threads in the cycle: " + (ids == null ? 0 : ids.length));
        System.out.println("fix: acquire locks in one global order (e.g. by id)");
    }

    static void lockBoth(Object first, Object second, CyclicBarrier barrier) {
        synchronized (first) {
            try { barrier.await(); } catch (Exception e) { return; }
            synchronized (second) { System.out.println("never printed"); }
        }
    }
}

