const { Worker, isMainThread, workerData } = require('worker_threads');
// No built-in detector: a watchdog uses lock timeouts, so a stuck worker reports itself.
// shared memory: [0]=lockA [1]=lockB [2]=arrived [3]=stuck
function tryLock(m, i, ms) {
  const end = Date.now() + ms;
  while (Atomics.compareExchange(m, i, 0, 1) !== 0) {
    const left = end - Date.now();
    if (left <= 0) return false;       // tryLock with timeout
    Atomics.wait(m, i, 1, left);
  }
  return true;
}
function unlock(m, i) { Atomics.store(m, i, 0); Atomics.notify(m, i, 1); }

if (isMainThread) {
  const m = new Int32Array(new SharedArrayBuffer(16));
  let done = 0;
  for (const [first, second] of [[0, 1], [1, 0]]) { // A then B, and B then A
    new Worker(__filename, { workerData: { buf: m.buffer, first, second } }).on('exit', () => {
      if (++done < 2) return;
      console.log("deadlock detected: " + (m[3] > 0));
      console.log("threads in the cycle: " + m[3]);
      console.log("fix: acquire locks in one global order (e.g. by id)");
    });
  }
} else {
  const m = new Int32Array(workerData.buf), { first, second } = workerData;
  tryLock(m, first, 5000);
  Atomics.add(m, 2, 1);
  while (Atomics.load(m, 2) < 2) { /* both workers now hold their first lock */ }
  if (tryLock(m, second, 300)) unlock(m, second);
  else Atomics.add(m, 3, 1);          // circular wait: report instead of hanging
  unlock(m, first);
}

