public class Main {
    public static void main(String[] args) throws Exception {
        Semaphore limit = new Semaphore(3);                   // cap concurrent calls to a downstream service
        AtomicInteger running = new AtomicInteger(), maxSeen = new AtomicInteger(), done = new AtomicInteger();
        try (ExecutorService ex = Executors.newVirtualThreadPerTaskExecutor()) { // one cheap thread per task, never pooled
            for (int i = 0; i < 20; i++) {
                ex.submit(() -> {
                    try {
                        limit.acquire();                       // blocking is cheap on a virtual thread
                        try {
                            int now = running.incrementAndGet();
                            maxSeen.accumulateAndGet(now, Math::max);
                            Thread.sleep(20);                  // pretend remote call
                            running.decrementAndGet();
                        } finally { limit.release(); }
                        done.incrementAndGet();
                    } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
                });
            }
        } // close() waits for all tasks
        System.out.println("tasks completed: " + done.get());
        System.out.println("max concurrent calls <= 3: " + (maxSeen.get() <= 3));
    }
}

