// Promise-based semaphore: tasks are cheap, the semaphore caps concurrent downstream calls
class Semaphore {
  constructor(n) { this.n = n; this.waiters = []; }
  async acquire() {
    if (this.n > 0) { this.n--; return; }
    await new Promise(r => this.waiters.push(r)); // permit is handed over directly
  }
  release() {
    if (this.waiters.length) this.waiters.shift()(); else this.n++;
  }
}

async function main() {
  const limit = new Semaphore(3);
  let running = 0, maxSeen = 0, done = 0;
  const task = async () => {
    await limit.acquire();
    try {
      running++; maxSeen = Math.max(maxSeen, running);
      await new Promise(r => setTimeout(r, 20)); // pretend remote call
      running--;
    } finally { limit.release(); }
    done++;
  };
  await Promise.all(Array.from({ length: 20 }, task));
  console.log("tasks completed: " + done);
  console.log("max concurrent calls <= 3: " + (maxSeen <= 3));
}
main();

