import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class Main {
    // Class under test: a bank where total money must never change
    static class Bank {
        final int[] bal = {500, 500};
        synchronized void move(int from, int to, int amt) { bal[from] -= amt; bal[to] += amt; }
        synchronized int total() { return bal[0] + bal[1]; }
    }

    public static void main(String[] args) throws Exception {
        int threads = 8, iters = 5000;
        Bank bank = new Bank();
        CountDownLatch ready = new CountDownLatch(threads), go = new CountDownLatch(1);
        ExecutorService ex = Executors.newFixedThreadPool(threads);
        List<Future<?>> fs = new ArrayList<>();
        for (int t = 0; t < threads; t++) {
            final int dir = t % 2;
            fs.add(ex.submit(() -> {
                ready.countDown();
                try { go.await(); } catch (InterruptedException e) { return; } // all threads collide together
                for (int i = 0; i < iters; i++) bank.move(dir, 1 - dir, 1);
            }));
        }
        ready.await(); go.countDown();
        for (Future<?> f : fs) f.get(10, TimeUnit.SECONDS);   // bounded wait: a hang becomes a failure
        ex.shutdown();
        System.out.println("invariant total == 1000: " + (bank.total() == 1000));
        System.out.println("4 threads each way, net change per side = 0: " + (bank.bal[0] == 500 && bank.bal[1] == 500));
    }
}

